INSERT INTO public.source_pages (import_run_id, book_id, source_page, page_kind, raw_transcription, chapter_heading, topic_heading, confidence, extraction_method, model_name, notes, review_metadata) SELECT (SELECT id FROM public.import_runs WHERE pipeline_version = 'vision-quality-gated-batch-0484-0488-v1' ORDER BY started_at DESC LIMIT 1), b.id, 486, 'educational'::page_kind, 'টেস্ট ক্রিকেটে বাংলাদেশ ♦ বাংলাদেশ বিশ্বের- দশম টেস্ট খেলুড়ে দেশ। ♦ বাংলাদেশ ক্রিকেট দলের অভিষেক টেস্ট অনুষ্ঠিত হয়- ২০০০ সালে, ঢাকায়। ♦ বাংলাদেশ অভিষেক টেস্ট খেলে- ভারতের বিপক্ষে। ♦ বাংলাদেশের পক্ষে টেস্ট ক্রিকেটে প্রথম হ্যাটট্রিক অর্জনকারী বোলার- অলক কাপালি (২০০৩ সালে); পাকিস্তানের বিপক্ষে। ♦ টেস্ট ক্রিকেটে বাংলাদেশের পক্ষে প্রথম ডাবল সেঞ্চুরি করেন- মুশফিকুর রহিম। ♦ টেস্ট ক্রিকেটে বাংলাদেশের এক ইনিংসে সর্বোচ্চ রান- ৬৩৮ রান (শ্রীলঙ্কার বিপক্ষে)। অলিম্পিকে বাংলাদেশ ♦ বাংলাদেশ বিশ্ব অলিম্পিকে প্রথম অংশগ্রহণ করে- লস এঞ্জেলসে, ১৯৮৪ সালে। ♦ বিশ্ব অলিম্পিকে বাংলাদেশের প্রথম অংশগ্রহণ ছিল- ২৩তম অলিম্পিকে। ফুটবলে বাংলাদেশ ♦ বাংলাদেশ ফিফার সদস্যপদ লাভ করে- ১ জানুয়ারি, ১৯৭৬ সালে। ♦ বাংলাদেশ প্রথম বিশ্বকাপ ফুটবলের বাছাইপর্বে অংশগ্রহণ করে- ১৯৮৬ সালে। ♦ ঢাকা প্রথম বিভাগ ফুটবল লীগ শুরু হয়- ১৯১৫ সাল থেকে। ♦ বাংলাদেশের ফুটবল ইতিহাসের শ্রেষ্ঠ খেলোয়াড়- যাদুকর সামাদ। ♦ স্বাধীন বাংলা ফুটবল দলের অধিনায়ক ছিলেন- জাকারিয়া পিন্টু। বাংলাদেশের দাবাড়ু ♦ দাবা খেলার সর্বোচ্চ খেতাব- গ্র্যান্ডমাস্টার। ♦ বাংলাদেশের সর্বশ্রেষ্ঠ দাবাড়ু- নিয়াজ মোর্শেদ। ♦ বাংলাদেশে একমাত্র আন্তর্জাতিক মহিলা দাবাড়ু- রানী হামিদ। ♦ দাবায় গ্র্যান্ডমাস্টার উপাধি পেয়েছেন ৫ জন বাংলাদেশি- ➢ নিয়াজ মোর্শেদ ➢ আব্দুল্লাহ আল রাকিব ➢ রিফাত বিন সাত্তার ➢ জিয়াউর রহমান ➢ এনামুল হোসেন রাজীব। বাংলাদেশ ক্রীড়া শিক্ষা প্রতিষ্ঠান (BKSP) • স্থাপিত হয়- ১৯৮৬ সালে। • অবস্থান- জিরানী, সাভার। • বিকেএসপির মূল শিক্ষা কার্যক্রম- উচ্চমাধ্যমিক পর্যন্ত। • উদ্দেশ্য- জাতীয় পর্যায়ে খেলাধুলার মান উন্নয়ন এবং আন্তর্জাতিক ক্রীড়াঙ্গনে বাংলাদেশের অবস্থানকে সম্মানজনক অবস্থায় উন্নীত করা। বাংলাদেশে একমাত্র ক্রীড়া শিক্ষাকেন্দ্র বিকেএসপি Zubair''s GK - ৪২৯', 'বাংলাদেশের খেলাধুলা', 'বিভিন্ন খেলা