INSERT INTO public.source_pages (import_run_id, book_id, source_page, page_kind, raw_transcription, chapter_heading, topic_heading, confidence, extraction_method, model_name, notes, review_metadata) SELECT (SELECT id FROM public.import_runs WHERE pipeline_version = 'vision-quality-gated-batch-0484-0488-v1' ORDER BY started_at DESC LIMIT 1), b.id, 488, 'mcq'::page_kind, 'এই অধ্যায়ের সাথে জড়িত বিগত বছরের প্রশ্ন ঢাকা বিশ্ববিদ্যালয় ০১. স্বাধীন বাংলা ফুটবল দলের অধিনায়ক কে ছিলেন? [DU খ ২৩-২৪] ক. কাজী সালাউদ্দিন খ. জাকারিয়া পিন্টু গ. সাইদুর রহমান প্যাটেল ঘ. অমলেশ সেন ০২. বাংলাদেশ জাতীয় নারী ক্রিকেট দল কবে টেস্ট মর্যাদা লাভ করে? [DU ঘ ২১-২২] ক. ১ এপ্রিল ২০২১ খ. ১০ এপ্রিল ২০২১ গ. ২০ এপ্রিল ২০২১ ঘ. ৩০ এপ্রিল ২০২১ ০৩. ২০২০ সালের অনুরূর্ধ্ব-১৯ বিশ্বকাপ বিজয়ী বাংলাদেশ ক্রিকেট দলের অধিনায়ক কে ছিলেন? (DU খ ২০-২১) ক. আকবর আলী খ. শামীম হোসেন গ. শরীফুল ইসলাম ঘ. তৌহিদ হৃদয় ০৪. টোকিও অলিম্পিক গেমস ২০২০ এর কোন ইভেন্টে বাংলাদেশ প্রথমবারের মত দ্বিতীয় পর্বে পৌঁছেছিল? (DU ঘ ২০-২১) ক. সাঁতার খ. ধনুবিদ্যা গ. শুটিং ঘ. অ্যাথলেটিকস্ ০৫. টেস্ট ক্রিকেটে বাংলাদেশের পক্ষে প্রথম ডাবল সেঞ্চুরি কে করেন? [DU ঘ ১৬-১৭] ক. মোহাম্মদ আশরাফুল খ. মমিনুল হক গ. তামিম ইকবাল ঘ. মুশফিকুর রহিম ০৬. বাংলাদেশের প্রথম টেস্ট ক্রিকেট দলের অধিনায়ক কে ছিলেন? [DU ঙ ০৩-০৪/চবি-ঘ, ০৭-০৮] ক. আকরাম খান খ. আমিনুল ইসলাম গ. নাঈমুর রহমান ঘ. খালেদ মাসুদ ০৭. বিশ্বকাপ ক্রিকেট কোন দলের বিরুদ্ধে বাংলাদেশ প্রথম জয়লাভ করে? [DU খ ০৮-০৯] ক. স্কটল্যান্ড খ. মালয়েশিয়া গ. পাকিস্তান ঘ. কেনিয়া ০৮. বাংলাদেশ বিশ্বকাপ ক্রিকেট প্রতিযোগিতায় প্রথম যে দেশের বিরুদ্ধে ম্যাচ খেলেছিল- [DU খ ০৪-০৫] ক. স্কটল্যান্ড খ. নিউজিল্যান্ড গ. পাকিস্তান ঘ. জিম্বাবুয়ে বি সি এস ০৯. বাংলাদেশ........সাল থেকে গ্রীষ্মকালীন অলিম্পিকে অংশগ্রহণ করে আসছে- (30 BCS) ক. ১৯৮৫ খ. ১৯৮৪ গ. ১৯৮৬ ঘ. ১৯৮৩ ১০. বাংলাদেশ কত সালে ক্রিকেট টেস্ট স্ট্যাটাস লাভ করে? [37,30,25 BCS] ক. ১৫ জুন ১৯৯৭ খ. ২৬ জুন ১৯৯৭ গ. ২৬ জুন ২০০০ ঘ. ২৫ মে ২০০৪ ১১. প্রথম আইসিসি ট্রফিতে বাংলাদেশ দলের অধিনায়ক কে ছিলেন? [26 BCS] ক. আশরাফ হোসেন লিপু খ. আকরাম খান গ. আমিনুল ইসলাম বুলবুল ঘ. শফিকুল হক হীরা ১২. বাংলাদেশের পক্ষে ওয়ানডে অভিষেকে কোন ক্রিকেটার পাঁচ উইকেট পেয়েছেন? [35 BCS] ক. সোহাগ গাজী খ. রুবেল হোসেন গ. তাইজুল ইসলাম ঘ. তাসকিন আহমেদ অন্যান্য বিশ্ববিদ্যালয় ও অন্যান্য চাকুরির পরীক্ষা ১৩. ১৯৭১ সালে স্বাধীন বাংলা ফুটবল দলের অধিনায়ক কে ছিলেন? [MC 24-25] ক. এনায়েতুর রহমান খান খ. প্রতাপ শংকর হাজরা গ. মেজর হাফিজ উদ্দিন আহমদ ঘ. জাকারিয়া পিন্টু ১৪. কোন সালে বাংলাদেশ ক্রিকেট ওয়ানডে স্ট্যাটাস লাভ করে? [MC 19-20] ক. ১৯৯৮ খ. ১৯৯৯ গ. ১৯৯৬ ঘ. ১৯৯৭ ১৫. বাংলাদেশ কততম টেস্ট প্লেয়িং দেশ হিসাবে স্বীকৃতি পেয়েছে? [শাবি-খ, ০৩-০৪] ক. অষ্টম খ. দশম গ. নবম ঘ. এগারতম ১৬. বাংলাদেশ প্রথম কোন সালে অলিম্পিকে অংশগ্রহণ করে? [মাধ্যমিক সহকারী শিক্ষক, ০৯] ক. ১৯৮৪ খ. ২০০০ গ. ১৯৯৬ ঘ. ১৯৭২ উত্তরমালা ১. খ ২. ক ৩. ক ৪. খ ৫. ঘ ৬. গ ৭. ক ৮. খ ৯. খ ১০. গ ১১. ঘ ১২. ঘ ১৩. ঘ ১৪. ঘ ১৫. খ ১৬. ক Zubair''s GK - 489', 'বাংলাদেশের খেলাধুলা', 'এই অধ্যায়ের সাথে জড়িত বিগত বছরের প্রশ্ন', 'high'::confidence_level, 'vision_ocr_with_image_grounded_review', 'gemini-3-flash-preview', 'Quality-gated source extraction with visual review, semantic separation, and verification ledger.', '{"source_image_sha256":"62bb9650d88b211b6d6207224f80f2b7e9047e89e7dbf70e76ecbceb09d3ee0b","extraction_model":"gemini-3-flash-preview","review_status":"accepted_with_flags","corrections":[{"transcribed_text":"[DU খ ১৬-১৭]","source_reading":"[DU ঘ ১৬-১৭]","reason":"Corrected the unit letter based on visual evidence."},{"transcribed_text":"[DU ভ ০৩-০৪]","source_reading":"[DU ঙ ০৩-০৪]","reason":"Corrected the unit letter ''ঙ'' which was misread as ''ভ''."},{"transcribed_text":"(50 BCS)","source_reading":"(30 BCS)","reason":"Corrected the BCS exam number from 50 to 30 as per the image."}],"unresolved_spans":[],"accepted_content_tags":["topic_heading","mcq","mcq_option","answer_key","exam_metadata","misc"],"physical_source_page":488,"printed_book_page":431,"nested_artifact_page_number":489,"page_number_mismatch":"Nested OCR page metadata differs from the physical PDF page; physical source page and reviewed footer are canonical.","visual_revie